#!/usr/bin/env node
'use strict';

/**
 * process-toggle-summary.js
 * ------------------------------------------------------------
 * Finds the latest Puppeteer toggle summary (generated by
 * n8n-toggle-workflows-ui.js), copies it into validation-results/,
 * generates a human-readable Markdown digest, and pushes a condensed
 * summary into the Alex AI RAG ingest workflow.
 */

const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const RUNS_DIR = path.join(process.cwd(), 'reports', 'n8n-toggle-runs');
const OUTPUT_DIR = path.join(process.cwd(), 'validation-results');

function getLatestSummaryPath() {
  if (!fs.existsSync(RUNS_DIR)) {
    throw new Error(`Toggle runs directory not found: ${RUNS_DIR}`);
  }

  const entries = fs
    .readdirSync(RUNS_DIR, { withFileTypes: true })
    .filter((ent) => ent.isDirectory())
    .map((ent) => ({
      name: ent.name,
      mtime: fs.statSync(path.join(RUNS_DIR, ent.name)).mtimeMs,
    }))
    .sort((a, b) => b.mtime - a.mtime);

  if (entries.length === 0) {
    throw new Error(`No toggle runs available in ${RUNS_DIR}`);
  }

  const latestDir = entries[0].name;
  const summaryPath = path.join(RUNS_DIR, latestDir, 'summary.json');
  if (!fs.existsSync(summaryPath)) {
    throw new Error(`Latest toggle run missing summary.json: ${summaryPath}`);
  }

  return { dir: latestDir, summaryPath };
}

function writeOutputs(summary, dirName) {
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });

  const baseName = `n8n-toggle-summary-${dirName}`;
  const jsonPath = path.join(OUTPUT_DIR, `${baseName}.json`);
  const markdownPath = path.join(OUTPUT_DIR, `${baseName}.md`);

  fs.writeFileSync(jsonPath, JSON.stringify(summary, null, 2), 'utf8');

  const failures = summary.workflows.filter((wf) => wf.status !== 'success');
  const webhookIssues = summary.webhookTests.filter(
    (test) => test.status !== 'working'
  );

  const mdLines = [
    `# n8n Crew Toggle Run – ${summary.timestamp}`,
    '',
    `- Toggle Directory: \`${summary.runDirectory}\``,
    `- Summary File: \`${summary.summaryFile}\``,
    `- Workflows Toggled: ${summary.results.success}/${summary.results.total}`,
    `- Webhooks Working: ${summary.webhookResults.working}/${summary.webhookTests.length}`,
    `- Duration: ${summary.durationSeconds}s`,
    '',
    '## Workflow Failures',
  ];

  if (failures.length === 0) {
    mdLines.push('- None 🎉');
  } else {
    failures.forEach((wf) => {
      mdLines.push(
        `- **${wf.name}** (ID: ${wf.id}) – errors: ${wf.errors.join('; ')}`
      );
    });
  }

  mdLines.push('', '## Webhook Issues');
  if (webhookIssues.length === 0) {
    mdLines.push('- All webhooks responded (working)');
  } else {
    webhookIssues.forEach((wh) => {
      mdLines.push(
        `- **${wh.name}** (${wh.path}) – status: ${wh.status}${
          wh.httpStatus ? ` (HTTP ${wh.httpStatus})` : ''
        }${wh.error ? ` – ${wh.error}` : ''}`
      );
    });
  }

  if (summary.errors?.length) {
    mdLines.push('', '## Automation Errors');
    summary.errors.forEach((err) => mdLines.push(`- ${err}`));
  }

  fs.writeFileSync(markdownPath, mdLines.join('\n'), 'utf8');

  return { jsonPath, markdownPath };
}

function pushToRag(summary) {
  const failures = summary.workflows.filter((wf) => wf.status !== 'success');
  const webhookIssues = summary.webhookTests.filter(
    (test) => test.status !== 'working'
  );

  const summaryText = `Crew webhook toggle run – ${summary.results.success}/${summary.results.total} workflows toggled, ${summary.webhookResults.working}/${summary.webhookTests.length} webhooks working.`;

  const features = [
    `workflows_total=${summary.results.total}`,
    `workflows_success=${summary.results.success}`,
    `webhooks_working=${summary.webhookResults.working}`,
    `webhooks_total=${summary.webhookTests.length}`,
    `workflow_failures=${failures.map((wf) => wf.name).join(', ') || 'none'}`,
    `webhook_issues=${
      webhookIssues.map((wh) => wh.name).join(', ') || 'none'
    }`,
  ].join('; ');

  const result = spawnSync(
    'node',
    [
      'scripts/n8n-post-knowledge.js',
      '--summary',
      summaryText,
      '--features',
      features,
      '--tags',
      'toggle-run,webhooks,automation',
    ],
    { stdio: 'inherit' }
  );

  if (result.status !== 0) {
    console.warn(
      '⚠️  Failed to push toggle summary to RAG (non-blocking). Exit code:',
      result.status
    );
  }
}

function main() {
  const { dir, summaryPath } = getLatestSummaryPath();
  const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf8'));

  const outputs = writeOutputs(summary, dir);
  console.log('✅ Toggle summary copied to validation-results:');
  console.log(`   JSON: ${outputs.jsonPath}`);
  console.log(`   Markdown: ${outputs.markdownPath}`);

  if (process.env.ALEX_AI_DISABLE_RAG !== 'true') {
    pushToRag(summary);
  } else {
    console.log('ℹ️  RAG push disabled via ALEX_AI_DISABLE_RAG=true');
  }
}

if (require.main === module) {
  try {
    main();
  } catch (error) {
    console.error(`❌ ${error.message}`);
    process.exit(1);
  }
}


